/**
 * A resource server AM may mint an ID-JAG towards, behind this authority's authorization server.
 * @export
 * @interface CrossAppAccessResourceServer
 */
export interface CrossAppAccessResourceServer {
    /**
     * Identifier generated by AM. Echo it back on update to keep this resource server's identity across a rename or a new resource; anything else is given a new one.
     * @type {string}
     * @memberof CrossAppAccessResourceServer
     */
    id?: string;
    /**
     * Label the resource server is known by.
     * @type {string}
     * @memberof CrossAppAccessResourceServer
     */
    name?: string;
    /**
     * Resource identifier of the resource server, as defined by RFC 8707. Carried by the "resource" claim of the ID-JAG. An absolute URI, unique within this authority.
     * @type {string}
     * @memberof CrossAppAccessResourceServer
     */
    resource?: string;
}
/**
 * Check if a given object implements the CrossAppAccessResourceServer interface.
 */
export declare function instanceOfCrossAppAccessResourceServer(value: object): value is CrossAppAccessResourceServer;
export declare function CrossAppAccessResourceServerFromJSON(json: any): CrossAppAccessResourceServer;
export declare function CrossAppAccessResourceServerFromJSONTyped(json: any, ignoreDiscriminator: boolean): CrossAppAccessResourceServer;
export declare function CrossAppAccessResourceServerToJSON(json: any): CrossAppAccessResourceServer;
export declare function CrossAppAccessResourceServerToJSONTyped(value?: CrossAppAccessResourceServer | null, ignoreDiscriminator?: boolean): any;
